void worker_task(int id, int& counter) {
    // Thread entry point
    counter += id;
}

// Basic Thread Creation (C++)
int shared_val = 0;
std::thread t1(worker_task, 5, std::ref(shared_val));
std::thread t2(worker_task, 8, std::ref(shared_val));

// Synchronization management
t1.join(); // Wait for t1 to finish
t2.join(); // Wait for t2 to finish


// Manual Mutex Usage (C++ Style)
std::mutex mtx;
int shared_resource = 0;

void unsafe_access() {
    shared_resource++; // Race Condition Risk
}

void safe_access_manual() {
    mtx.lock();       // Acquire lock
    shared_resource++;
    // Must remember to unlock!
    mtx.unlock();     // Release lock
}


// RAII Locking (std::lock_guard) - Preferred
std::mutex mtx_raii;

void safe_access_raii() {
    // Lock acquired upon construction
    std::lock_guard<std::mutex> lock(mtx_raii);

    // Critical Section
    shared_resource = 42;

    // Lock automatically released upon scope exit
    // (even if exception is thrown)
}


// Atomic Operations (Lock-Free Primitives)
std::atomic<int> atomic_counter(0);

void atomic_increment() {
    // Guaranteed consistency without explicit mutex
    atomic_counter++; // atomic_counter.fetch_add(1)
}

int current_val = atomic_counter.load();


// Guaranteed One-Time Initialization
std::once_flag init_flag;
Resource* R_singleton = nullptr;

void init_singleton() {
    std::call_once(init_flag, [](){
        // Lambda executed exactly once
        R_singleton = new Resource();
    });
}
